#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

void solve(){
    int n;
    cin >> n;
    int total_students = 3*n;
    vector<ll> arr(total_students+1);
    
    
    for(int i = 1; i <= total_students; i++){
        cin >> arr[i];
    }
    
    sort(arr.begin()+1 , arr.end() , greater<ll>()) ;
    
    vector<ll> prr(total_students+1,0);
    for(int i=1 ; i<=total_students ; i++){
        prr[i]=prr[i-1] + arr[i] ;
    }
    
    ll maxscore = 0 ;
    
    for(int i=0 ; i<=n ; i++){
        int l =0 , r=n-i-1 ;
        int best = 0 ;
        while(l<=r){
            int mid = l + (r-l)/2 ;
            ll diff = arr[i+2*mid+1] + arr[i+2*mid+2]-3LL*arr[3*n-2*i-mid];
            if(diff>=0){
                best = mid+1 ;
                l = mid+1 ;
            }
            else{
                r = mid-1 ;
            }
        }
        ll currentscore = 2LL*prr[i] + prr[i+2*best] + 3LL*prr[3*n-2*i-best];
        
        if(currentscore>maxscore){
            maxscore = currentscore ;
        }
    }
    
    cout<<maxscore<<endl;
}

int main() {
	// your code goes here
    int t;
    cin >> t;
    
    while(t--){
        solve();
    }
}
